(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.01+t*0.15)*8+Math.cos((y+w1y)*0.012-t*0.1)*6;
  const w2y = Math.cos((y+w1y)*0.01-t*0.12)*8+Math.sin((x+w1x)*0.011+t*0.18)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*70, 120+Math.cos(t*0.65+2)*55, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+1)*60, 100+Math.sin(t*0.75+4)*65, 0.065, 2.4, 1.15],
    [200+Math.sin(t*0.25+6)*110, 30+Math.cos(t*0.85)*45, 0.095, 1.8, 0.88]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    const d2=Math.sqrt((sx-sY*0.5+100)**2+(sy-sX*0.6-40)**2);
    aS2+=Math.cos(d2*f*0.8-t*sp*0.5+2.0)*w;
    iS2+=Math.sin(d2*f*0.5-t*sp*0.4+0.8)*w;
  }
  const n=src.length, act=aS/n, inh=iS/n, act2=aS2/n, inh2=iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.03+ang*2-t*0.8)*Math.cos(dist*0.07-ang*5+t*1.8)*0.25;
  const coupling=Math.tanh((act2-inh2*0.6)*1.8)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+coupling)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.15;
  const blend=reaction*0.6+cell*0.2+micro*0.2, v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,95],[18,95,125],[30,160,145],[180,195,80],[220,155,55],[195,85,65],[130,35,70],[65,18,55],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
